window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dd93f84f3f3f52c3"]={"versions": [{"id": "FIG-dd93f84f3f3f52c3", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm CONTINUOUS</code>) des AUTOSAR Classic ADC-Treibers (Mikrocontroller-Abstraktionsschicht, MCAL). Das Diagramm modelliert die hierarchische Zustandsstruktur für ADC-Kanalgruppen im kontinuierlichen Konvertierungsmodus (<code>CONTINUOUS</code>) bei Auslösung durch Software-Trigger (<code>SW-TRIGGER</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände</strong>:</li>\n<li>Übergeordneter Zustand <code>CONTINUOUS</code>.</li>\n<li>Zusammengesetzter Zustand <code>SW-TRIGGER</code> mit zwei orthogonalen Regionen/Zweigen.</li>\n<li>Subzustände <code>SINGLE-ACCESS</code> und <code>STREAMING-ACCESS</code> (jeweils mit Verweis-Symbol für unterlagerte Subzustandsmaschinen).</li>\n<li><strong>Pseudozustände</strong>:</li>\n<li>Initialzustand (schwarzer Punkt) auf Ebene des Zustands <code>SW-TRIGGER</code>.</li>\n<li>Initialzustände (schwarze Punkte) innerhalb der beiden Regionen <code>SINGLE-ACCESS</code> und <code>STREAMING-ACCESS</code>.</li>\n<li><strong>Bedingungen / Guards</strong>:</li>\n<li><code>[SINGLE-ACCESS]</code>: Wächterbedingung für den Eintritt in die Region für Einzelzugriff.</li>\n<li><code>[STREAMING-ACCESS]</code>: Wächterbedingung für den Eintritt in die Region für Streaming-Zugriff.</li>\n<li><strong>Kommentar-Notiz</strong>: Erläuterung zur Konfigurationsabhängigkeit der Zustände.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Bei Eintritt in den kontinuierlichen Software-Trigger-Modus (<code>SW-TRIGGER</code>) verzweigt der Kontrollfluss deterministisch anhand der konfigurierten Pufferzugriffsart der ADC-Kanalgruppe.</li>\n<li>Ist die Gruppe für Einzelwertzugriff konfiguriert, wird über die Bedingung <code>[SINGLE-ACCESS]</code> der Subzustand <code>SINGLE-ACCESS</code> eingenommen.</li>\n<li>Ist die Gruppe für Streaming-Zugriff konfiguriert, wird über die Bedingung <code>[STREAMING-ACCESS]</code> der Subzustand <code>STREAMING-ACCESS</code> eingenommen.</li>\n<li>Beide Pfade führen in eigenständige, detaillierte Sub-Zustandsautomaten (angedeutet durch das Sub-State-Icon), welche die spezifische Pufferhandhabung und Abtastzyklen des kontinuierlichen Betriebs abwickeln.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die formale Darstellung als parallele Regionen dient hier der kompakten Modellierung zweier exklusiver Konfigurationspfade. Gemäß der normativen Anmerkung im Diagramm („The 'concurrent states' SINGLE-ACCESS and STREAMING-ACCESS are configuration options for ADC groups. One ADC group can be only in one of the two states.“) schließt die statische Gruppenkonfiguration eine gleichzeitige Ausführung beider Zustände für dieselbe ADC-Gruppe aus. Entwickler und Integratoren müssen beachten, dass der Pufferzugriffsmodus statisch konfiguriert wird und das Laufzeitverhalten der Wandlungsgruppe fest an die jeweilige Sub-Zustandsmaschine bindet.</p>"}, {"id": "FIG-619ae44cb5236c40", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm CONTINUOUS</code>) des AUTOSAR Classic ADC-Treibers (Mikrocontroller-Abstraktionsschicht, MCAL). Das Diagramm modelliert die hierarchische Zustandsstruktur für ADC-Kanalgruppen im kontinuierlichen Konvertierungsmodus (<code>CONTINUOUS</code>) bei Auslösung durch Software-Trigger (<code>SW-TRIGGER</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände</strong>:</li>\n<li>Übergeordneter Zustand <code>CONTINUOUS</code>.</li>\n<li>Zusammengesetzter Zustand <code>SW-TRIGGER</code> mit zwei orthogonalen Regionen/Zweigen.</li>\n<li>Subzustände <code>SINGLE-ACCESS</code> und <code>STREAMING-ACCESS</code> (jeweils mit Verweis-Symbol für unterlagerte Subzustandsmaschinen).</li>\n<li><strong>Pseudozustände</strong>:</li>\n<li>Initialzustand (schwarzer Punkt) auf Ebene des Zustands <code>SW-TRIGGER</code>.</li>\n<li>Initialzustände (schwarze Punkte) innerhalb der beiden Regionen <code>SINGLE-ACCESS</code> und <code>STREAMING-ACCESS</code>.</li>\n<li><strong>Bedingungen / Guards</strong>:</li>\n<li><code>[SINGLE-ACCESS]</code>: Wächterbedingung für den Eintritt in die Region für Einzelzugriff.</li>\n<li><code>[STREAMING-ACCESS]</code>: Wächterbedingung für den Eintritt in die Region für Streaming-Zugriff.</li>\n<li><strong>Kommentar-Notiz</strong>: Erläuterung zur Konfigurationsabhängigkeit der Zustände.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Bei Eintritt in den kontinuierlichen Software-Trigger-Modus (<code>SW-TRIGGER</code>) verzweigt der Kontrollfluss deterministisch anhand der konfigurierten Pufferzugriffsart der ADC-Kanalgruppe.</li>\n<li>Ist die Gruppe für Einzelwertzugriff konfiguriert, wird über die Bedingung <code>[SINGLE-ACCESS]</code> der Subzustand <code>SINGLE-ACCESS</code> eingenommen.</li>\n<li>Ist die Gruppe für Streaming-Zugriff konfiguriert, wird über die Bedingung <code>[STREAMING-ACCESS]</code> der Subzustand <code>STREAMING-ACCESS</code> eingenommen.</li>\n<li>Beide Pfade führen in eigenständige, detaillierte Sub-Zustandsautomaten (angedeutet durch das Sub-State-Icon), welche die spezifische Pufferhandhabung und Abtastzyklen des kontinuierlichen Betriebs abwickeln.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die formale Darstellung als parallele Regionen dient hier der kompakten Modellierung zweier exklusiver Konfigurationspfade. Gemäß der normativen Anmerkung im Diagramm („The 'concurrent states' SINGLE-ACCESS and STREAMING-ACCESS are configuration options for ADC groups. One ADC group can be only in one of the two states.“) schließt die statische Gruppenkonfiguration eine gleichzeitige Ausführung beider Zustände für dieselbe ADC-Gruppe aus. Entwickler und Integratoren müssen beachten, dass der Pufferzugriffsmodus statisch konfiguriert wird und das Laufzeitverhalten der Wandlungsgruppe fest an die jeweilige Sub-Zustandsmaschine bindet.</p>"}], "trans": [{"from": "FIG-dd93f84f3f3f52c3", "to": "FIG-619ae44cb5236c40", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
